import {DIMENSIONS} from './city-dimensions.mjs';
import {paletteFor} from './city-settings.mjs';
import * as T from 'three';
import {GLTFLoader} from '../vendor/loaders/GLTFLoader.js';
import {createCitySimulation} from './city-simulation.mjs';
const cache=new Map(),loader=new GLTFLoader();
export async function createCityAdapter(seed,options={},saved){
 let sim=createCitySimulation(seed,options,saved);const plan=sim.plan,root=new T.Group();root.scale.setScalar(.1);const owned=[],actors=[],materials=new Map(),palette=paletteFor(plan.settings);const keys=['RCred','RCplum','RClilac','RCbrass','RCcream','RCglass','RCdark','RCgreen'];
 const ids=Array.from({length:30},(_,i)=>'RC-'+String(i+1).padStart(3,'0')).concat('GF-008');
 await Promise.all(ids.map(async id=>{if(!cache.has(id))cache.set(id,(await loader.loadAsync(new URL('./assets/'+id+'.glb',import.meta.url).href)).scene);}));
 function model(id){const o=cache.get(id).clone(true);o.traverse(m=>{if(m.isMesh){m.castShadow=m.receiveShadow=true;m.userData.sharedGeometry=true;const recolor=mat=>{const i=keys.indexOf(mat.name);if(i<0){mat.userData.shared=true;return mat;}if(!materials.has(mat)){const copy=mat.clone();copy.color.set(palette.colors[i]);copy.userData.shared=true;materials.set(mat,copy);}return materials.get(mat);};m.material=Array.isArray(m.material)?m.material.map(recolor):recolor(m.material);}});return o;}
 function mesh(g,color){const m=new T.Mesh(g,new T.MeshStandardMaterial({color,roughness:.95}));owned.push(m);m.receiveShadow=true;return m;}
 function place(id,x,z,y=0,rotation=0){const o=model(id);o.position.set(x,y,z);o.rotation.y=rotation;root.add(o);return o;}
 for(const district of plan.districts){const {center,turn,roads}=district;
 const terrain=mesh(new T.CylinderGeometry(plan.radius,plan.radius,1.2,6),palette.ground);terrain.userData.cityTerrain={center};terrain.position.set(center.x,-.6,center.z);root.add(terrain);
 for(const r of roads){const road=mesh(new T.RingGeometry(r-2,r+2,64),palette.colors[6]);road.rotation.x=-Math.PI/2;road.position.set(center.x,.035,center.z);root.add(road);const curb=mesh(new T.RingGeometry(r+2,r+4,64),palette.colors[4]);curb.rotation.x=-Math.PI/2;curb.position.set(center.x,.045,center.z);root.add(curb);}
 for(let i=0;i<16;i+=4){const a=turn+i*Math.PI/8,o=mesh(new T.BoxGeometry(4,.06,roads.length===2?38:20),palette.colors[6]);o.position.set(center.x+Math.sin(a)*(roads.length===2?18:10),.04,center.z+Math.cos(a)*(roads.length===2?18:10));o.rotation.y=a;root.add(o);}
 const plaza=mesh(new T.CylinderGeometry(12,12,.12,40),palette.colors[4]);plaza.position.set(center.x,.04,center.z);root.add(plaza);
 for(let i=0;i<16;i++){const n=plan.nodes[district.nodeOffset+i],a=turn+i*Math.PI/8;place('RC-022',center.x+(n.x-center.x)*1.04,center.z+(n.z-center.z)*1.04);if(i%2===0)place('RC-024',center.x+(n.x-center.x)*.62,center.z+(n.z-center.z)*.62);if(i%4===1)place('RC-023',center.x+(n.x-center.x)*.64,center.z+(n.z-center.z)*.64,0,a);}
 place('RC-026',center.x-9,center.z+1);place('RC-025',center.x+9,center.z+4);place('RC-027',center.x,center.z+(roads.length===2?37:19));place('RC-030',center.x+10,center.z-6);
 for(let i=0;i<8;i++){const a=turn+i*Math.PI/4;place('RC-029',center.x+Math.sin(a)*12,center.z+Math.cos(a)*12);}
 }
 for(const {from,to}of plan.connectors){const dx=to.x-from.x,dz=to.z-from.z,road=mesh(new T.BoxGeometry(4,.07,Math.hypot(dx,dz)),palette.colors[6]);road.position.set((from.x+to.x)/2,.06,(from.z+to.z)/2);road.rotation.y=Math.atan2(dx,dz);root.add(road);}
 for(const p of plan.placements){const o=place(p.asset,p.x,p.z,.12,p.rotation);o.scale.fromArray(p.scale||[1,1,1]);for(const part of p.attachments||[]){const addition=model(part.asset);addition.position.y=part.y;addition.scale.fromArray(part.scale);o.add(addition);}o.userData.inspect={title:p.label,kind:'Diorama · '+p.role,description:'Generated street frontage. Building geometry is registered in the asset workshop.'};o.userData.liveReadout=()=>{const site=sim.state.sites.find(s=>s.id===p.id);return site?`${site.parcels.toFixed(0)} parcels · ${site.visits} deliveries`:p.role==='depot'?`${sim.state.stock.parcels.toFixed(0)} parcels remaining`:'Public observatory · no research economy simulated';};}
 const flightHeight=Math.max(...plan.placements.map(p=>DIMENSIONS[p.asset][2]*(p.scale?.[1]||1)))+8;
 const airships=Array.from({length:plan.settings.airships},(_,i)=>{const o=place('RC-021',0,0,flightHeight+Math.floor(i/plan.districts.length)*6);o.userData.inspect={title:'Airship '+(i+1),kind:'Diorama · ambient traffic',description:'Decorative flight circuit; no passengers or flight simulation.'};return o;});
 const cars=Array.from({length:plan.settings.traffic},(_,i)=>place('RC-'+String(18+i%3).padStart(3,'0'),0,0));
 for(const person of [...sim.workers,...sim.residents]){const body=place('GF-008',person.position.x,person.position.z,.12);body.userData.inspect={title:person.name,kind:person.id.startsWith('courier')?'Parcel courier':'Resident',description:person.id.startsWith('courier')?'Moves real finite parcel stock between depot and buildings.':'Walks between connected street destinations; visits are spatial activity.'};actors.push({id:person.id,body,get phase(){return [...sim.workers,...sim.residents].find(p=>p.id===person.id).phase;}});}
 function present(){for(const a of actors){const p=[...sim.workers,...sim.residents].find(p=>p.id===a.id);a.body.position.set(p.position.x,.12,p.position.z);a.body.rotation.y=p.heading||0;a.body.userData.activity=p.phase;a.body.userData.liveReadout=()=>p.job?`${p.phase} · ${p.job.load} parcels in hand`:`${p.phase} · ${p.visits||0} visits`;}const t=sim.state.seconds;for(const [i,c]of cars.entries()){const d=plan.districts[i%plan.districts.length],a=t*.035+i*Math.PI*2/Math.max(1,cars.length),r=d.roads[i%d.roads.length];c.position.set(d.center.x+Math.sin(a)*r,.1,d.center.z+Math.cos(a)*r);c.rotation.y=a+Math.PI/2;}for(const [i,ship]of airships.entries()){const d=plan.districts[i%plan.districts.length],a=t*(.006+i*.0003)+i*2.4;ship.position.set(d.center.x+Math.sin(a)*plan.radius*.7,flightHeight+Math.floor(i/plan.districts.length)*6,d.center.z+Math.cos(a)*plan.radius*.6);ship.rotation.y=a+Math.PI/2;}}

 const fitPoints=[];for(const d of plan.districts)for(let i=0;i<6;i++){const a=i*Math.PI/3;fitPoints.push(new T.Vector3((d.center.x+Math.sin(a)*plan.radius)*.1,0,(d.center.z+Math.cos(a)*plan.radius)*.1));}for(const p of plan.placements){const h=DIMENSIONS[p.asset][2]*(p.scale?.[1]||1);for(const x of [-p.radius,p.radius])for(const z of [-p.radius,p.radius])fitPoints.push(new T.Vector3((p.x+x)*.1,h*.1,(p.z+z)*.1));}if(airships.length)for(const d of plan.districts)for(let i=0;i<8;i++){const a=i*Math.PI/4;fitPoints.push(new T.Vector3((d.center.x+Math.sin(a)*plan.radius*.7)*.1,(flightHeight+Math.floor((airships.length-1)/plan.districts.length)*6+5)*.1,(d.center.z+Math.cos(a)*plan.radius*.6)*.1));}
 present();const life={get state(){return sim.state;},workers:actors,places:plan.placements,update(dt){sim.update(Math.min(60,dt));present();},snapshot:()=>sim.snapshot(),restore(s){sim=createCitySimulation(seed,options,s);present();},summary:()=>({animals:0,buildings:plan.placements.length,residents:sim.residents.length+sim.workers.length,delivered:sim.state.delivered.parcels,jobs:sim.state.jobs,stock:sim.state.stock.parcels}),navigation:()=>({workers:sim.workers.map(w=>({...w.position,phase:w.phase})),connected:true}),notices:()=>sim.state.stock.parcels===0?[{text:'Depot empty. This city has finite parcel stock; regeneration creates a new supply.'}]:[],dispose:()=>sim.dispose(),get readout(){return `${sim.state.stock.parcels.toFixed(0)} depot parcels · ${sim.state.delivered.parcels.toFixed(0)} delivered · ${sim.state.jobs} completed deliveries`;}};
 return {group:root,plan,life,fitPoints,heightAt:()=>0,recipe:{name:'Futurama '+seed,seed,tiles:[]},assembly:{plans:[{id:'city-1',placements:plan.placements,paths:plan.edges,plantedAssets:[]}]},tileObjects:[],fitBounds:new T.Box3(new T.Vector3(Math.min(...plan.districts.map(d=>d.center.x-plan.radius))*.1,-.12,Math.min(...plan.districts.map(d=>d.center.z-plan.radius))*.1),new T.Vector3(Math.max(...plan.districts.map(d=>d.center.x+plan.radius))*.1,Math.max(6,plan.settings.airships?(flightHeight+Math.floor((plan.settings.airships-1)/plan.districts.length)*6+5)*.1:0),Math.max(...plan.districts.map(d=>d.center.z+plan.radius))*.1)),dispose(){for(const m of materials.values())m.dispose();for(const o of owned){o.geometry.dispose();o.material.dispose();}}};
}
